const characterReferenceSheets = {"1":{"size":[923,1280],"x":20,"w":655,"ys":[90,470,850],"h":310,"detailX":680,"panels":[[86,259,444],[464,637,822],[846,1024,1207]]},"2":{"size":[853,1280],"x":20,"w":610,"ys":[150,500,860],"h":290,"detailX":645,"panels":[[138,288,449],[498,648,806],[856,1011,1170]]},"3":{"size":[942,1280],"x":20,"w":675,"ys":[105,490,875],"h":305,"detailX":698,"panels":[[105,272,454],[490,664,843],[884,1032,1227]]},"4":{"size":[954,1280],"x":20,"w":680,"ys":[100,480,870],"h":300,"detailX":709,"panels":[[107,268,422],[479,626,778],[861,1018,1182]]},"5":{"size":[923,1280],"x":20,"w":675,"ys":[120,490,850],"h":300,"detailX":694,"panels":[[124,312,444],[487,677,808],[856,1049,1179]]},"6":{"size":[923,1280],"x":20,"w":675,"ys":[90,465,840],"h":310,"detailX":702,"panels":[[83,264,434],[460,641,806],[840,1022,1219]]},"7":{"size":[923,1280],"x":25,"w":665,"ys":[95,460,835],"h":295,"detailX":700,"panels":[[86,275,421],[456,639,793],[829,1015,1187]]},"8":{"size":[945,1280],"x":20,"w":680,"ys":[112,495,865],"h":300,"detailX":705,"panels":[[107,275,438],[480,643,814],[861,1032,1197]]}};
function characterReference(ci,ki){const pair=[[2,7],[4,1],[8,6],[3,5]][ci];const sheet=pair[ki<3?0:1],row=ki%3,data=characterReferenceSheets[sheet];return {...data,sheet,row,y:data.ys[row],url:new URL('pictures/character-reference-'+sheet+'.jpg',document.baseURI).href};}
function characterPhoto(ci,ki,id='character',detail=null){const r=characterReference(ci,ki);let rect=[r.x,r.y,r.w,r.h];if(detail){const [top,split,bottom]=r.panels[r.row];const dy=detail==='enter'?top:split+4;rect=[r.detailX,dy,r.size[0]-r.detailX-10,(detail==='enter'?split-4:bottom)-dy];}const [x,y,w,h]=rect;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 378" role="img" aria-label="Character Z-84 ${detail||'keyboard'} reference"><defs><clipPath id="${id}-reference-crop"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><svg width="900" height="378" viewBox="${rect.join(' ')}" preserveAspectRatio="xMidYMid meet" overflow="hidden"><image href="${r.url}" width="${r.size[0]}" height="${r.size[1]}" clip-path="url(#${id}-reference-crop)"/></svg></svg>`;}
function renderCharacterDetails(){const host=document.querySelector('#character-details');if(!host)return;host.hidden=selectedModel==='mountain';if(host.hidden)return;host.innerHTML=['enter','spacebar'].map(detail=>`<figure>${characterPhoto(selectedCase,selectedKey,'character-detail-'+detail,detail)}<figcaption>${detail==='enter'?'Enter · signature accent':'Spacebar · flowing artwork'}</figcaption></figure>`).join('');}
